css:
:root{--ds-amber:#E3A857;--ds-amber-dim:#8A6A3C;--ds-line:#1F2226;--ds-tick:#5C5852;--ds-steel:#8EA4B8;--ds-steel-dim:#5E7184;--ds-mono:"SF Mono",ui-monospace,"JetBrains Mono",Menlo,monospace}
:root:not(.dark){--ds-amber:#9A6420;--ds-amber-dim:#B8956A;--ds-line:#CFCBC4;--ds-tick:#A39D94;--ds-steel:#3F6584;--ds-steel-dim:#7F97AC}
::selection{background:rgba(227,168,87,.28);color:inherit}

.dark [data-workspace-area="conversation"]{background-color:#0A0B0D !important;background-image:radial-gradient(circle at 8px 8px,rgba(200,194,184,.13) .7px,transparent 1.05px) !important;background-size:16px 16px !important;background-repeat:repeat !important}
:root:not(.dark) [data-workspace-area="conversation"]{background-color:#EDEBE6 !important;background-image:radial-gradient(circle at 8px 8px,rgba(40,46,52,.20) .7px,transparent 1.05px) !important;background-size:16px 16px !important;background-repeat:repeat !important}

[data-chat-header]{font-family:var(--ds-mono) !important;letter-spacing:.02em !important;border-bottom:1px solid transparent !important;border-image:linear-gradient(90deg,transparent,rgba(227,168,87,.38) 50%,transparent) 1 !important}

.chat-markdown h1{font-weight:500 !important;letter-spacing:-.01em}
.chat-markdown h2{font-weight:500 !important;padding-bottom:.4em;border-bottom:1px solid var(--ds-line);border-image:linear-gradient(90deg,var(--ds-amber) 0 20px,var(--ds-line) 20px) 1}
.chat-markdown h3{font-family:var(--ds-mono);text-transform:uppercase;letter-spacing:.12em;font-size:.76em !important;color:var(--ds-steel)}
.chat-markdown strong{color:#F4F1EB}
:root:not(.dark) .chat-markdown strong{color:#000}
.chat-markdown a{color:inherit !important;text-decoration:underline !important;text-decoration-style:dotted !important;text-decoration-color:var(--ds-amber) !important;text-underline-offset:3px;text-decoration-thickness:1px}
.chat-markdown a:hover{color:var(--ds-amber) !important}
.chat-markdown li::marker{color:var(--ds-steel-dim)}
.chat-markdown blockquote{border-left:1px solid var(--ds-steel) !important;font-style:normal}
.chat-markdown hr{border:0 !important;height:1px;background:var(--ds-line)}
.chat-markdown th{font-family:var(--ds-mono);font-weight:500 !important;text-transform:uppercase;letter-spacing:.08em;font-size:.74em;color:var(--ds-steel)}
.chat-markdown :not(pre)>code{border-radius:2px !important;color:#E9D2AE !important;background:rgba(227,168,87,.07) !important;box-shadow:inset 0 0 0 1px rgba(227,168,87,.13)}
:root:not(.dark) .chat-markdown :not(pre)>code{color:#6E4710 !important}

[data-user-message-bubble]{border-radius:2px !important;border:0 !important;box-shadow:none !important;background-image:linear-gradient(var(--ds-tick),var(--ds-tick)),linear-gradient(var(--ds-tick),var(--ds-tick)),linear-gradient(var(--ds-tick),var(--ds-tick)),linear-gradient(var(--ds-tick),var(--ds-tick)) !important;background-size:7px 1px,1px 7px,7px 1px,1px 7px !important;background-position:left top,left top,right bottom,right bottom !important;background-repeat:no-repeat !important}

.chat-markdown-codeblock{border-radius:2px !important;border:1px solid var(--ds-line) !important;box-shadow:inset 2px 0 0 rgba(227,168,87,.55)}
:root:not(.dark) .chat-markdown-codeblock{box-shadow:inset 2px 0 0 var(--ds-amber)}

[data-slot="composer-host"]{border-radius:3px !important;border:1px solid #2B2F35 !important;background:#0F1114 !important;box-shadow:none !important;transition:border-color .2s ease,box-shadow .35s ease}
[data-slot="composer-host"]:focus-within{border-color:rgba(227,168,87,.55) !important;box-shadow:0 0 0 1px rgba(227,168,87,.08),0 0 48px -16px rgba(227,168,87,.32) !important}
.composer-tiptap{caret-color:var(--ds-amber)}
:root:not(.dark) [data-slot="composer-host"]{background:#F9F8F6 !important;border-color:#C2BDB5 !important}

[data-slot="sidebar-inner"]{border-right:1px solid #131518 !important}
[data-thread-item],[data-thread-item] [data-sidebar-row]{border-radius:0 !important}
[data-thread-item] [aria-current]:not([aria-current="false"]){box-shadow:none !important;background-image:linear-gradient(var(--ds-amber),var(--ds-amber)),linear-gradient(var(--ds-amber),var(--ds-amber)),linear-gradient(var(--ds-amber),var(--ds-amber)),linear-gradient(var(--ds-amber),var(--ds-amber)) !important;background-size:8px 1px,1px 8px,8px 1px,1px 8px !important;background-position:left top,left top,right bottom,right bottom !important;background-repeat:no-repeat !important}
[data-slot="project-monogram"]{font-family:var(--ds-mono) !important;letter-spacing:.06em}

[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:3px !important}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:3px !important;border:1px solid #2B2F35 !important;box-shadow:0 1px 0 0 rgba(227,168,87,.35) inset,0 32px 64px -20px rgba(0,0,0,.85) !important}
[data-slot="tooltip-popup"]{font-family:var(--ds-mono) !important;letter-spacing:.02em;font-size:11px !important;border-radius:2px !important}
svg.lucide{stroke-width:1.6;stroke-linecap:square;stroke-linejoin:miter}

::-webkit-scrollbar{width:6px;height:6px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#22252A !important;border-radius:0 !important}
::-webkit-scrollbar-thumb:hover{background:var(--ds-amber) !important}
[data-slot="scroll-area-thumb"]{border-radius:0 !important;background:#22252A !important}
[data-slot="scroll-area-thumb"]:hover{background:var(--ds-amber) !important}

@media (prefers-reduced-motion:reduce){[data-slot="composer-host"]{transition:none !important}}
